aa<-grep('^--file=',commandArgs(FALSE),value=TRUE)
source(file.path(dirname(sub('^--file=','',aa[1])),'helpers/setup.R'))
co<-c('LN','HN','LU','HU','LA','HA');sets<-c('E1 growth-maintenance','S0 all','S0B precursor transport','C1/C2 adaptive reserve')
co<-c('LN','HN','LU','HU','LA','HA');cols<-paper_style$condition;shapes<-c(LN=1,HN=16,LU=2,HU=17,LA=0,HA=15);ltys<-c(LN='dashed',HN='solid',LU='dashed',HU='solid',LA='dashed',HA='solid')
m<-rd('Expression','module_sample_scores.tsv');m$condition<-factor(m$condition,levels=co);mods<-sets;it<-rd('Expression','Interaction_BH4_verified.tsv');it<-it[match(mods,it$score_module),];names0<-c('a  E1: maintenance-associated','b  S0: surface-interface','c  S0B: predicted precursor transport','d  C1/C2: reserve-associated');labs0<-setNames(paste0(names0,'\nSource \u00d7 level: F(2,12) = ',sprintf('%.2f',it$F_interaction),'; BH q = ',formatC(it$q_interaction_BH4,format='g',digits=3)),mods);m$panel<-factor(m$score_module,levels=mods)
m$x<-ave(seq_len(nrow(m)),interaction(m$panel,m$condition),FUN=function(i)seq_along(i));m$x<-as.integer(m$condition)+c(-.13,0,.13)[m$x]
ms7<-do.call(rbind,lapply(split(m,list(m$panel,m$condition),drop=TRUE),function(q)data.frame(panel=q$panel[1],condition=q$condition[1],mean=mean(q$score),se=sd(q$score)/sqrt(nrow(q)))))
p7<-ggplot(m,aes(x,score,colour=condition,shape=condition))+geom_point(size=1.9,stroke=.5)+geom_errorbar(data=ms7,aes(x=as.integer(condition),y=mean,ymin=mean-se,ymax=mean+se),width=.18,linewidth=.4,inherit.aes=FALSE,colour=ink)+geom_point(data=ms7,aes(x=as.integer(condition),y=mean),shape=18,size=2,inherit.aes=FALSE,colour=ink)+facet_wrap(~panel,ncol=2,scales='free_y',labeller=labeller(panel=labs0))+scale_colour_manual(values=cols)+scale_shape_manual(values=shapes)+scale_x_continuous(breaks=1:6,labels=co,limits=c(.5,6.5))+scale_y_continuous(expand=expansion(mult=c(.09,.11)))+labs(x=NULL,y='Mean VST expression score')+base_theme()+theme(legend.position='none',strip.background=element_blank(),strip.text=element_text(hjust=0,size=7.8,lineheight=1.2,margin=margin(b=8)),panel.spacing=unit(8,'mm'))
export_fig('FigureS9',function()print(p7),150)
